// Integer money and percentage helpers, equivalent to the Rust SDK primitives
// `Cents` and `Percentage` (rust/sdk/src/primitives.rs). The shared vectors in
// validation/x7e-money-vectors.json are generated by the Rust code and
// replayed by test/money.test.mjs.
//
// Representation: `Cents` holds an exact `bigint` in the Rust range 0..=2^64-1.
// JavaScript numbers lose precision above 2^53-1, so a `number` is accepted
// only when it is a safe integer, and `encode()` follows the SDK wire
// convention (a `number` when safe, otherwise a `bigint`, which the bridge
// carries as an exact decimal string). Nothing is ever rounded.
// `Percentage` is stored as integer basis points (0..=10000) in a `number`.
//
// Arithmetic is integer only. `Percentage.of` truncates towards zero, like
// Rust's `u64` division. Overflow and negative results throw a `RangeError`
// whose message equals the Rust `SdkError` message. They never wrap.

const U64_MAX = (1n << 64n) - 1n;
const U16_MAX = 65_535n;

function integer(value: unknown, what: string): bigint {
  if (typeof value === "bigint") return value;
  if (typeof value === "number" && Number.isSafeInteger(value)) return BigInt(value);
  if (typeof value === "number" && Number.isInteger(value)) {
    throw new RangeError(`${what} must be a safe integer or a bigint`);
  }
  throw new TypeError(`${what} must be an integer`);
}

function unsigned64(value: unknown, what: string): bigint {
  const exact = integer(value, what);
  if (exact < 0n || exact > U64_MAX) throw new RangeError(`${what} must be between 0 and 18446744073709551615`);
  return exact;
}

/** Mirrors Rust `u64::decode` / `u16::decode` for an already decoded plain value. */
function decodeUnsigned(value: unknown, max: bigint): bigint {
  if (typeof value === "bigint" || (typeof value === "number" && Number.isInteger(value))) {
    const exact = integer(value, "unsigned integer");
    if (exact < 0n) throw new TypeError("expected unsigned integer, received signed integer");
    if (exact > max) throw new RangeError("unsigned integer is out of range");
    return exact;
  }
  const kind = value === null ? "null" : typeof value === "boolean" ? "boolean" : typeof value === "string" ? "string"
    : value instanceof Uint8Array ? "bytes" : Array.isArray(value) ? "list" : typeof value;
  throw new TypeError(`expected unsigned integer, received ${kind}`);
}

/** Whole number of cents, `0 ..= 2^64 - 1`. Immutable. */
export class Cents {
  static readonly ZERO: Cents = new Cents(0n);
  readonly #cents: bigint;

  private constructor(cents: bigint) {
    this.#cents = cents;
    Object.freeze(this);
  }

  /** Rust `Cents::new`. Accepts a safe-integer `number` or a `bigint`. */
  static new(value: number | bigint): Cents {
    return new Cents(unsigned64(value, "Cents value"));
  }

  /** Rust `Cents::from_dollars`: whole dollars times 100, checked. */
  static fromDollars(dollars: number | bigint): Cents {
    const cents = unsigned64(dollars, "dollar amount") * 100n;
    if (cents > U64_MAX) throw new RangeError("dollar amount exceeds Cents range");
    return new Cents(cents);
  }

  /** Rust `Cents::decode` for a value decoded by the SDK (`number` or `bigint`). */
  static decode(value: unknown): Cents {
    return new Cents(decodeUnsigned(value, U64_MAX));
  }

  /** The exact amount in cents. */
  get value(): bigint {
    return this.#cents;
  }

  /** The amount as a `number`; throws instead of losing precision above 2^53 - 1. */
  toNumber(): number {
    if (this.#cents > BigInt(Number.MAX_SAFE_INTEGER)) {
      throw new RangeError("Cents value exceeds the JavaScript safe-integer range");
    }
    return Number(this.#cents);
  }

  /** Wire value: a `number` when safe, otherwise an exact `bigint`. */
  encode(): number | bigint {
    return this.#cents <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(this.#cents) : this.#cents;
  }

  min(other: Cents): Cents {
    return this.#cents <= other.#cents ? this : other;
  }

  /** Rust `Cents::checked_sub`: never negative. */
  checkedSub(other: Cents): Cents {
    if (other.#cents > this.#cents) throw new RangeError("currency subtraction would be negative");
    return new Cents(this.#cents - other.#cents);
  }

  /** `$<dollars>.<cents>`, for example `$1234.56`. */
  asCurrency(): string {
    return `$${this.#cents / 100n}.${(this.#cents % 100n).toString().padStart(2, "0")}`;
  }

  /** A saving: U+2212 MINUS SIGN before the currency text, for example `−$19.99`. */
  asSaving(): string {
    return `−${this.asCurrency()}`;
  }

  equals(other: Cents): boolean {
    return this.#cents === other.#cents;
  }

  compare(other: Cents): -1 | 0 | 1 {
    return this.#cents < other.#cents ? -1 : this.#cents > other.#cents ? 1 : 0;
  }

  toString(): string {
    return this.asCurrency();
  }
}

/** A percentage in whole basis points, `0 ..= 10000` (0% to 100%). Immutable. */
export class Percentage {
  readonly #basisPoints: number;

  private constructor(basisPoints: number) {
    this.#basisPoints = basisPoints;
    Object.freeze(this);
  }

  /** Rust `Percentage::from_whole`: 0 to 100 percent. */
  static fromWhole(value: number): Percentage {
    if (!Number.isInteger(value) || value < 0 || value > 100) {
      if (typeof value !== "number") throw new TypeError("percentage must be an integer");
      throw new RangeError("percentage must be between 0 and 100");
    }
    return new Percentage(value * 100);
  }

  /** Rust `Percentage::from_basis_points`: 0 to 10000. */
  static fromBasisPoints(value: number): Percentage {
    if (!Number.isInteger(value) || value < 0 || value > 10_000) {
      if (typeof value !== "number") throw new TypeError("basis points must be an integer");
      throw new RangeError("basis points must be between 0 and 10000");
    }
    return new Percentage(value);
  }

  /** Rust `Percentage::decode`: a `u16`, then the basis-point range. */
  static decode(value: unknown): Percentage {
    return Percentage.fromBasisPoints(Number(decodeUnsigned(value, U16_MAX)));
  }

  get basisPoints(): number {
    return this.#basisPoints;
  }

  /**
   * Rust `Percentage::of`: `amount * basisPoints / 10000`, truncated. Like
   * Rust, it throws when the intermediate product exceeds 2^64 - 1, even if
   * the quotient would fit.
   */
  of(amount: Cents): Cents {
    const product = amount.value * BigInt(this.#basisPoints);
    if (product > U64_MAX) throw new RangeError("percentage calculation overflowed");
    return Cents.new(product / 10_000n);
  }

  encode(): number {
    return this.#basisPoints;
  }

  equals(other: Percentage): boolean {
    return this.#basisPoints === other.#basisPoints;
  }

  compare(other: Percentage): -1 | 0 | 1 {
    return this.#basisPoints < other.#basisPoints ? -1 : this.#basisPoints > other.#basisPoints ? 1 : 0;
  }
}
